{{-
    [
        name for name in CTX.property_names
        if any (
            name[:part | length] == part or name[-(part | length):] == part
            for part in CTX.lookup_parts
        )
    ]
-}}

{% try %}
  {%- set lookup_parts = (CTX.lookup_property_name | lower).split("_") -%}
  {%- set matches = [prop for prop in CTX.hs_company_properties if prop.name | lower == CTX.lookup_property_name | lower] -%}
  {{- matches if matches | length > 0 else {
    "error": "NoMatchFound",
    "message": "No company property matched the provided field name.",
    "lookup_value": CTX.lookup_property_name,
    "similar_fields": [
      prop.name for prop in CTX.hs_company_properties
      if prop.name | lower is string and
         lookup_parts | select('in', prop.name | lower) | list | length > 0
    ]
  }|json -}}
{% catch %}
  {{- {
    "error": "LookupError",
    "message": "Unexpected error occurred during property lookup.",
    "lookup_value": CTX.lookup_property_name,
    "payload_results": CTX.hs_company_properties
  }|json -}}
{% endtry %}

